const HTML_PATH = '/workspace/sandbox/skills/building-accessible-ui/single-checkbox--framework-react--style-dark/claude-sonnet-4.6__s1/index.html';

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const html = fs.readFileSync(HTML_PATH, 'utf8');
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const r = await page.evaluate(async () => await window.axe.run());
  await browser.close();

  const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description, targets: v.nodes.map(n => n.target) })),
    bp:   bp.map(v =>   ({ id: v.id, impact: v.impact, description: v.description, targets: v.nodes.map(n => n.target) })),
    passes: r.passes.length
  }, null, 2));

  process.exit(wcag.length ? 1 : 0);
})();
